-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     TRUNC(SYSDATE)                                  AS \"Report Date\",     im.DEPT                                         AS \"Dept No\",     d.DEPT_NAME                                     AS \"Dept Name\",     im.CLASS                                        AS \"Class No\",     c.CLASS_NAME                                    AS \"Class Name\",     im.SUBCLASS                                     AS \"Subclass No\",     sc.SUB_NAME                                     AS \"Subclass Name\",     im.ITEM                                         AS \"Item ID\",     im.ITEM_DESC                                    AS \"Item Description\",     im.STANDARD_UOM                                 AS \"UOM\",     im.PACK_IND                                     AS \"Pack IND\",     im.STATUS                                       AS \"Item Status\",     ril.LOCATION                                    AS \"Location ID\",     il.LOC_TYPE                                     AS \"LOC Type\",     CASE il.LOC_TYPE             WHEN 'S'                 THEN 'Store'             WHEN 'W'                 THEN 'Warehouse'     END                                                 AS \"LOC Type DESC\",      CASE il.LOC_TYPE             WHEN 'S'                 THEN st.STORE_NAME             WHEN 'W'                 THEN wh.WH_NAME     END                                                 AS location_name,      il.STATUS                                       AS \"Item LOC Status\",     CASE il.STATUS             WHEN 'A'                 THEN 'Active'             WHEN 'C'                 THEN 'Discontinued'     END                                                 AS \"Item LOC Status DESC\",      ril.REPL_METHOD                                 AS \"Repl Method\",     CASE ril.REPL_METHOD             WHEN 'C'                 THEN 'Constant'             WHEN 'D'                 THEN 'Dynamic'             WHEN 'F'                 THEN 'Floating Point'             WHEN 'M'                 THEN 'Min/Max'             WHEN 'T'                 THEN 'Time Supply'             WHEN 'SO'                 THEN 'Store Orders'             WHEN 'DI'                 THEN 'Dynamic - Issues'             WHEN 'S'                 THEN 'Dynamic - Seasonal'             WHEN 'TI'                 THEN 'Time Supply - Issues'             WHEN 'E'                 THEN 'Time Supply - Seasonal'             ELSE ril.REPL_METHOD     END                                                 AS \"Repl Method DESC\",      ril.STOCK_CAT                                   AS \"Stock Category\",     CASE ril.STOCK_CAT             WHEN 'C'                 THEN 'Cross-Docked'             WHEN 'D'                 THEN 'Direct to Store'             WHEN 'L'                 THEN 'WH/Cross Link'             WHEN 'W'                 THEN 'Warehouse Stocked'             WHEN 'X'                 THEN 'PO Cross-link'     END                                                 AS \"Stock Category DESC\",      ril.REPL_ORDER_CTRL                             AS \"Order Control\",     CASE ril.REPL_ORDER_CTRL             WHEN 'A'                 THEN 'Automatic'             WHEN 'B'                 THEN 'Buyer Worksheet'             WHEN 'M'                 THEN 'Manual'             WHEN 'S'                 THEN 'Semi-Automatic'     END                                                 AS \"Order Control DESC\",      ril.PRIMARY_REPL_SUPPLIER                       AS \"Supplier ID\",     sp.SUP_NAME                                     AS \"Supplier Name\",     sp.SUP_STATUS                                   AS \"Supplier Status\",     ril.MIN_STOCK                                   AS \"Min Stock\",     ril.MAX_STOCK                                   AS \"Max Stock\",     ril.SOURCE_WH                                   AS \"Source Warehouse\",     ils.STOCK_ON_HAND                               AS \"Current Soh\",     ils.AV_COST                                     AS \"Weighted Avg Cost\",     il.SELLING_UNIT_RETAIL                          AS \"Unit Retail\",     ROUND(NVL(ils.STOCK_ON_HAND, 0) * NVL(ils.AV_COST, 0), 2)AS \"Soh Cost Value\",     CASE WHEN NVL(ils.STOCK_ON_HAND, 0) = 0 THEN 'OUT OF STOCK'             WHEN NVL(ils.STOCK_ON_HAND, 0) &lt; NVL(ril.MIN_STOCK, 0)                 THEN 'BELOW MIN'             WHEN NVL(ils.STOCK_ON_HAND, 0) &gt; NVL(ril.MAX_STOCK, 0)                 THEN 'ABOVE MAX'             ELSE 'WITHIN RANGE'     END                                                 AS \"Stock Position\",      last_rcpt.LAST_RECEIVE_DATE                     AS \"Last Receive Date\",     last_rcpt.LAST_RECEIVE_QTY                      AS \"Last Receive QTY\",     CASE             WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL                 THEN NULL             ELSE TRUNC(SYSDATE) - TRUNC(last_rcpt.LAST_RECEIVE_DATE)     END                                                 AS \"Days Since Last Receipt\",      last_roq.LAST_ROQ_DATE                          AS \"Last Roq Date\",     last_roq.LAST_ROQ_QTY                           AS \"Last Roq QTY\",     CASE             WHEN last_roq.LAST_ROQ_DATE IS NULL                 THEN NULL             ELSE TRUNC(SYSDATE) - TRUNC(last_roq.LAST_ROQ_DATE)     END                                                 AS \"Days Since Last Roq\",      NVL(open_po.OPEN_PO_COUNT, 0)                   AS \"Open PO Count\",     NVL(open_po.OPEN_PO_QTY, 0)                     AS \"Open PO QTY\",     open_po.OLDEST_PO_DATE                          AS \"Oldest Open PO Date\",     open_po.NEWEST_PO_DATE                          AS \"Newest Open PO Date\",     NVL(open_tsf.OPEN_TSF_COUNT, 0)                 AS \"Open Tsf Count\",     NVL(open_tsf.OPEN_TSF_QTY, 0)                   AS \"Open Tsf QTY\",     open_tsf.OLDEST_TSF_DATE                        AS \"Oldest Open Tsf Date\",     NVL(open_po.OPEN_PO_QTY, 0) + NVL(open_tsf.OPEN_TSF_QTY, 0)AS \"Total Open Supply QTY\",     CASE             WHEN smf.ITEM IS NOT NULL                 THEN 'Y'             ELSE 'N'     END                                                 AS \"Supplier Min Fail IND\",      smf.ERROR_MSG                                   AS \"Supplier Min Fail Msg\",     isc.LEAD_TIME                                   AS \"Lead Time\",     isc.PICKUP_LEAD_TIME                            AS \"Pickup Lead Time\",     isc.UNIT_COST                                   AS \"Unit Cost\",     isc.SUPP_PACK_SIZE                              AS \"Supp Pack Size\",     CASE             WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL                 THEN 'Y'             ELSE 'N'     END                                                 AS \"Ex Never Received\",      CASE             WHEN NVL(ils.STOCK_ON_HAND, 0) = 0 AND NVL(open_po.OPEN_PO_QTY, 0) = 0 AND NVL(open_tsf.OPEN_TSF_QTY, 0) = 0                 THEN 'Y'             ELSE 'N'     END                                                 AS \"Ex Oos No Supply\",      CASE             WHEN smf.ITEM IS NOT NULL                 THEN 'Y'             ELSE 'N'     END                                                 AS \"Ex Supplier Min Fail\",      CASE             WHEN last_roq.LAST_ROQ_DATE IS NULL OR TRUNC(last_roq.LAST_ROQ_DATE) &lt; TRUNC(SYSDATE) - 7                 THEN 'Y'             ELSE 'N'     END                                                 AS \"Ex No Roq 7 Days\",      CASE             WHEN NVL(ils.STOCK_ON_HAND, 0) &lt; NVL(ril.MIN_STOCK, 0) AND NVL(open_po.OPEN_PO_QTY, 0) = 0 AND NVL(open_tsf.OPEN_TSF_QTY, 0) = 0                 THEN 'Y'             ELSE 'N'     END                                                 AS \"Ex Below Min No Supply\",      CASE             WHEN NVL(sp.SUP_STATUS, 'X') != 'A' AND ril.STOCK_CAT IN ('C','D','L','W')                 THEN 'Y'             ELSE 'N'     END                                                 AS \"Ex Inactive Supplier\",      CASE             WHEN NVL(isc.PICKUP_LEAD_TIME, 0) = 0 AND ril.STOCK_CAT IN ('C','D','L','W')                 THEN 'Y'             ELSE 'N'     END                                                 AS \"Ex Missing Pickup Lt\",      CASE             WHEN NVL(isc.UNIT_COST, 0) = 0                 THEN 'Y'             ELSE 'N'     END                                                 AS \"Ex Missing Unit Cost\",      (CASE WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL THEN 1 ELSE 0 END + CASE WHEN NVL(ils.STOCK_ON_HAND,0)=0 AND NVL(open_po.OPEN_PO_QTY,0)=0 AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 1 ELSE 0 END + CASE WHEN smf.ITEM IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN last_roq.LAST_ROQ_DATE IS NULL OR TRUNC(last_roq.LAST_ROQ_DATE) &lt; TRUNC(SYSDATE)-7 THEN 1 ELSE 0 END + CASE WHEN NVL(ils.STOCK_ON_HAND,0) &lt; NVL(ril.MIN_STOCK,0) AND NVL(open_po.OPEN_PO_QTY,0)=0 AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 1 ELSE 0 END + CASE WHEN NVL(sp.SUP_STATUS,'X')!='A' AND ril.STOCK_CAT IN ('C','D','L','W') THEN 1 ELSE 0 END + CASE WHEN NVL(isc.PICKUP_LEAD_TIME,0)=0 AND ril.STOCK_CAT IN ('C','D','L','W') THEN 1 ELSE 0 END + CASE WHEN NVL(isc.UNIT_COST,0)=0 THEN 1 ELSE 0 END )AS \"Total Exception Count\",     CASE WHEN NVL(ils.STOCK_ON_HAND,0)=0 AND NVL(open_po.OPEN_PO_QTY,0)=0 AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 'CRITICAL - OOS with No Supply'             WHEN smf.ITEM IS NOT NULL                 THEN 'HIGH - Supplier Minimum Failure'             WHEN NVL(sp.SUP_STATUS,'X')!='A' AND ril.STOCK_CAT IN ('C','D','L','W')                 THEN 'HIGH - Inactive Supplier on Repl'             WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL                 THEN 'HIGH - Never Received'             WHEN NVL(ils.STOCK_ON_HAND,0) &lt; NVL(ril.MIN_STOCK,0) AND NVL(open_po.OPEN_PO_QTY,0)=0 AND NVL(open_tsf.OPEN_TSF_QTY,0)=0                 THEN 'HIGH - Below Min, No Open Supply'             WHEN last_roq.LAST_ROQ_DATE IS NULL OR TRUNC(last_roq.LAST_ROQ_DATE) &lt; TRUNC(SYSDATE)-7                 THEN 'MEDIUM - No ROQ in 7 Days'             WHEN NVL(isc.PICKUP_LEAD_TIME,0)=0 AND ril.STOCK_CAT IN ('C','D','L','W')                 THEN 'MEDIUM - Missing Pickup Lead Time'             WHEN NVL(isc.UNIT_COST,0)=0                 THEN 'MEDIUM - Missing Unit Cost'             ELSE 'LOW - Monitor'     END                                                 AS \"Exception Priority\",      CASE WHEN NVL(ils.STOCK_ON_HAND,0)=0 AND NVL(open_po.OPEN_PO_QTY,0)=0 AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 'Raise emergency PO or transfer immediately; review rplext batch log'             WHEN smf.ITEM IS NOT NULL                 THEN 'Review supplier minimum setup on SUP_INV_MGMT; adjust order qty or min'             WHEN NVL(sp.SUP_STATUS,'X')!='A'                 THEN 'Reactivate supplier or assign alternate supplier on REPL_ITEM_LOC'             WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL                 THEN 'Verify item is ordered and supplier relationship is active; check SHIPMENT table'             WHEN NVL(ils.STOCK_ON_HAND,0) &lt; NVL(ril.MIN_STOCK,0) AND NVL(open_po.OPEN_PO_QTY,0)=0                 THEN 'Repl below min with no open order - check rplext.ksh batch and order control'             WHEN last_roq.LAST_ROQ_DATE IS NULL                 THEN 'No ROQ ever generated - verify replenishment batch ran and REPL_DAY configured'             WHEN TRUNC(last_roq.LAST_ROQ_DATE) &lt; TRUNC(SYSDATE)-7                 THEN 'ROQ not generated in 7 days - check REPL_DAY schedule and rplext batch logs'             WHEN NVL(isc.PICKUP_LEAD_TIME,0)=0                 THEN 'Set PICKUP_LEAD_TIME on ITEM_SUPP_COUNTRY for this supplier'             WHEN NVL(isc.UNIT_COST,0)=0                 THEN 'Set UNIT_COST on ITEM_SUPP_COUNTRY - cost required for PO generation'             ELSE 'Review batch logs and replenishment configuration'     END                                                 AS \"Recommended Action\",      ril.LAST_UPDATE_DATETIME                        AS \"Last Repl Attr Update\"  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM         = il.ITEM                                                      AND  ril.LOCATION     = il.LOC                                                      AND  ril.LOC_TYPE     = il.LOC_TYPE     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM         = im.ITEM                                                      AND  im.TRAN_LEVEL    = im.ITEM_LEVEL     JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT          = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT          = c.DEPT                                                      AND  im.CLASS         = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT          = sc.DEPT                                                      AND  im.CLASS         = sc.CLASS                                                      AND  im.SUBCLASS      = sc.SUBCLASS     LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION     = st.STORE                                                      AND  il.LOC_TYPE      = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION     = wh.WH                                                      AND  il.LOC_TYPE      = 'W'     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH    ils    ON  ril.ITEM         = ils.ITEM                                                      AND  ril.LOCATION     = ils.LOC                                                      AND  ils.LOC_TYPE     = ril.LOC_TYPE     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM         = isc.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER = isc.SUPPLIER                                                      AND  isc.PRIMARY_SUPP_IND      = 'Y'                                                      AND  isc.PRIMARY_COUNTRY_IND   = 'Y'     LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp    ON  ril.PRIMARY_REPL_SUPPLIER = sp.SUPPLIER      LEFT JOIN (

-- ── Query 2 ────────────────────────────────────────────────────────────
SELECT             ss.ITEM,             sh.TO_LOC                                     AS loc,             MAX(sh.RECEIVE_DATE)                          AS last_receive_date,             SUM(ss.QTY_RECEIVED)                          AS last_receive_qty         FROM  MFCS_RDS.RDS_WV_SHIPSKU              ss         JOIN  MFCS_RDS.RDS_WV_SHIPMENT             sh  ON  ss.SHIPMENT = sh.SHIPMENT         GROUP BY ss.ITEM, sh.TO_LOC     ) last_rcpt                                           ON  ril.ITEM     = last_rcpt.ITEM                                                          AND  ril.LOCATION = last_rcpt.loc      LEFT JOIN (

-- ── Query 3 ────────────────────────────────────────────────────────────
SELECT             rr.ITEM,             rr.LOCATION,             rr.LOC_TYPE,             MAX(rr.REPL_DATE)                             AS last_roq_date,             MAX(rr.ORDER_ROQ)                 KEEP (DENSE_RANK LAST ORDER BY rr.REPL_DATE)                                                           AS last_roq_qty         FROM  MFCS_RDS.RDS_WV_REPL_RESULTS         rr         GROUP BY rr.ITEM, rr.LOCATION, rr.LOC_TYPE     ) last_roq                                            ON  ril.ITEM     = last_roq.ITEM                                                          AND  ril.LOCATION = last_roq.LOCATION                                                          AND  ril.LOC_TYPE = last_roq.LOC_TYPE      LEFT JOIN (

-- ── Query 4 ────────────────────────────────────────────────────────────
SELECT             ol.ITEM,             ol.LOCATION,             COUNT(DISTINCT oh.ORDER_NO)                   AS open_po_count,             SUM(ol.QTY_ORDERED - NVL(ol.QTY_RECEIVED, 0)) AS open_po_qty,             MIN(oh.WRITTEN_DATE)                          AS oldest_po_date,             MAX(oh.WRITTEN_DATE)                          AS newest_po_date         FROM  MFCS_RDS.RDS_WV_ORDLOC               ol         JOIN  MFCS_RDS.RDS_WV_ORDHEAD              oh  ON  ol.ORDER_NO = oh.ORDER_NO         WHERE oh.STATUS IN ('W','S','A')         GROUP BY ol.ITEM, ol.LOCATION     ) open_po                                             ON  ril.ITEM     = open_po.ITEM                                                          AND  ril.LOCATION = open_po.LOCATION      LEFT JOIN (

-- ── Query 5 ────────────────────────────────────────────────────────────
SELECT             td.ITEM,             th.TO_LOC                                     AS loc,             COUNT(DISTINCT th.TSF_NO)                     AS open_tsf_count,             SUM(td.TSF_QTY - NVL(td.RECEIVED_QTY, 0))    AS open_tsf_qty,             MIN(th.CREATE_DATE)                           AS oldest_tsf_date         FROM  MFCS_RDS.RDS_WV_TSFDETAIL            td         JOIN  MFCS_RDS.RDS_WV_TSFHEAD              th  ON  td.TSF_NO = th.TSF_NO         WHERE th.STATUS IN ('A','S','IR')         GROUP BY td.ITEM, th.TO_LOC     ) open_tsf                                            ON  ril.ITEM     = open_tsf.ITEM                                                          AND  ril.LOCATION = open_tsf.loc      LEFT JOIN MFCS_RDS.RDS_WV_SUPS_MIN_FAIL       smf  ON  ril.ITEM       = smf.ITEM                                                         AND  ril.PRIMARY_REPL_SUPPLIER = smf.SUPPLIER  WHERE     ril.REPL_METHOD  IS NOT NULL     AND il.STATUS    IN ('A','C')     AND im.STATUS     = 'A'     AND (         last_rcpt.LAST_RECEIVE_DATE IS NULL         OR (NVL(ils.STOCK_ON_HAND,0)=0             AND NVL(open_po.OPEN_PO_QTY,0)=0             AND NVL(open_tsf.OPEN_TSF_QTY,0)=0)         OR smf.ITEM IS NOT NULL         OR last_roq.LAST_ROQ_DATE IS NULL         OR TRUNC(last_roq.LAST_ROQ_DATE) &lt; TRUNC(SYSDATE)-7         OR (NVL(ils.STOCK_ON_HAND,0) &lt; NVL(ril.MIN_STOCK,0)             AND NVL(open_po.OPEN_PO_QTY,0)=0             AND NVL(open_tsf.OPEN_TSF_QTY,0)=0)         OR NVL(sp.SUP_STATUS,'X') != 'A'         OR (NVL(isc.PICKUP_LEAD_TIME,0)=0             AND ril.STOCK_CAT IN ('C','D','L','W'))         OR NVL(isc.UNIT_COST,0)=0     )  ORDER BY     (CASE WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL THEN 1 ELSE 0 END      + CASE WHEN NVL(ils.STOCK_ON_HAND,0)=0                  AND NVL(open_po.OPEN_PO_QTY,0)=0                  AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 1 ELSE 0 END      + CASE WHEN smf.ITEM IS NOT NULL THEN 1 ELSE 0 END      + CASE WHEN last_roq.LAST_ROQ_DATE IS NULL                  OR TRUNC(last_roq.LAST_ROQ_DATE) &lt; TRUNC(SYSDATE)-7 THEN 1 ELSE 0 END      + CASE WHEN NVL(ils.STOCK_ON_HAND,0) &lt; NVL(ril.MIN_STOCK,0)                  AND NVL(open_po.OPEN_PO_QTY,0)=0                  AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 1 ELSE 0 END      + CASE WHEN NVL(sp.SUP_STATUS,'X')!='A'                  AND ril.STOCK_CAT IN ('C','D','L','W') THEN 1 ELSE 0 END      + CASE WHEN NVL(isc.PICKUP_LEAD_TIME,0)=0                  AND ril.STOCK_CAT IN ('C','D','L','W') THEN 1 ELSE 0 END      + CASE WHEN NVL(isc.UNIT_COST,0)=0 THEN 1 ELSE 0 END     ) DESC,     CASE         WHEN NVL(ils.STOCK_ON_HAND,0)=0              AND NVL(open_po.OPEN_PO_QTY,0)=0              AND NVL(open_tsf.OPEN_TSF_QTY,0)=0         THEN 'CRITICAL - OOS with No Supply'         WHEN smf.ITEM IS NOT NULL THEN 'HIGH - Supplier Minimum Failure'         WHEN NVL(sp.SUP_STATUS,'X')!='A'              AND ril.STOCK_CAT IN ('C','D','L','W') THEN 'HIGH - Inactive Supplier on Repl'         WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL THEN 'HIGH - Never Received'         WHEN NVL(ils.STOCK_ON_HAND,0) &lt; NVL(ril.MIN_STOCK,0)              AND NVL(open_po.OPEN_PO_QTY,0)=0              AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 'HIGH - Below Min, No Open Supply'         ELSE 'MEDIUM'     END,     d.DEPT_NAME,     im.ITEM_DESC,     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Report Date</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>Dept No</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Dept Name</ds:name><ds:datatype>varchar(120)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Class No</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Class Name</ds:name><ds:datatype>v