ck\",\"isUserCalculation\":false},{\"prepColumnName\":\"Source Warehouse\",\"isUserCalculation\":false},{\"prepColumnName\":\"Current Soh\",\"isUserCalculation\":false},{\"prepColumnName\":\"Weighted Avg Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Unit Retail\",\"isUserCalculation\":false},{\"prepColumnName\":\"Soh Cost Value\",\"isUserCalculation\":false},{\"prepColumnName\":\"Stock Position\",\"isUserCalculation\":false},{\"prepColumnName\":\"Last Receive Date\",\"isUserCalculation\":false},{\"prepColumnName\":\"Last Receive QTY\",\"isUserCalculation\":false},{\"prepColumnName\":\"Days Since Last Receipt\",\"isUserCalculation\":false},{\"prepColumnName\":\"Last Roq Date\",\"isUserCalculation\":false},{\"prepColumnName\":\"Last Roq QTY\",\"isUserCalculation\":false},{\"prepColumnName\":\"Days Since Last Roq\",\"isUserCalculation\":false},{\"prepColumnName\":\"Open PO Count\",\"isUserCalculation\":false},{\"prepColumnName\":\"Open PO QTY\",\"isUserCalculation\":false},{\"prepColumnName\":\"Oldest Open PO Date\",\"isUserCalculation\":false},{\"prepColumnName\":\"Newest Open PO Date\",\"isUserCalculation\":false},{\"prepColumnName\":\"Open Tsf Count\",\"isUserCalculation\":false},{\"prepColumnName\":\"Open Tsf QTY\",\"isUserCalculation\":false},{\"prepColumnName\":\"Oldest Open Tsf Date\",\"isUserCalculation\":false},{\"prepColumnName\":\"Total Open Supply QTY\",\"isUserCalculation\":false},{\"prepColumnName\":\"Supplier Min Fail IND\",\"isUserCalculation\":false},{\"prepColumnName\":\"Supplier Min Fail Msg\",\"isUserCalculation\":false},{\"prepColumnName\":\"Lead Time\",\"isUserCalculation\":false},{\"prepColumnName\":\"Pickup Lead Time\",\"isUserCalculation\":false},{\"prepColumnName\":\"Unit Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Supp Pack Size\",\"isUserCalculation\":false},{\"prepColumnName\":\"Ex Never Received\",\"isUserCalculation\":false},{\"prepColumnName\":\"Ex Oos No Supply\",\"isUserCalculation\":false},{\"prepColumnName\":\"Ex Supplier Min Fail\",\"isUserCalculation\":false},{\"prepColumnName\":\"Ex No Roq 7 Days\",\"isUserCalculation\":false},{\"prepColumnName\":\"Ex Below Min No Supply\",\"isUserCalculation\":false},{\"prepColumnName\":\"Ex Inactive Supplier\",\"isUserCalculation\":false},{\"prepColumnName\":\"Ex Missing Pickup Lt\",\"isUserCalculation\":false},{\"prepColumnName\":\"Ex Missing Unit Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Total Exception Count\",\"isUserCalculation\":false},{\"prepColumnName\":\"Exception Priority\",\"isUserCalculation\":false},{\"prepColumnName\":\"Recommended Action\",\"isUserCalculation\":false},{\"prepColumnName\":\"Last Repl Attr Update\",\"isUserCalculation\":false}],\"transforms\":[{\"id\":\"1\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Dept No\"],\"expressionSourceColumns\":[\"Dept No\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Dept No\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Dept No\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":null},{\"id\":\"2\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Class No\"],\"expressionSourceColumns\":[\"Class No\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Class No\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Class No\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"1\"},{\"id\":\"3\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Subclass No\"],\"expressionSourceColumns\":[\"Subclass No\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Subclass No\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Subclass No\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"2\"},{\"id\":\"4\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Location ID\"],\"expressionSourceColumns\":[\"Location ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Location ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Location ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"3\"},{\"id\":\"5\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Supplier ID\"],\"expressionSourceColumns\":[\"Supplier ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Supplier ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Supplier ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"4\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 6 ────────────────────────────────────────────────────────────
SELECT\\n            ss.ITEM,\\n            sh.TO_LOC                                     AS loc,\\n            MAX(sh.RECEIVE_DATE)                          AS last_receive_date,\\n            SUM(ss.QTY_RECEIVED)                          AS last_receive_qty\\n        FROM  MFCS_RDS.RDS_WV_SHIPSKU              ss\\n        JOIN  MFCS_RDS.RDS_WV_SHIPMENT             sh  ON  ss.SHIPMENT = sh.SHIPMENT\\n        GROUP BY ss.ITEM, sh.TO_LOC\\n    ) last_rcpt                                           ON  ril.ITEM     = last_rcpt.ITEM\\n                                                         AND  ril.LOCATION = last_rcpt.loc\\n\\n    LEFT JOIN (\\n

-- ── Query 7 ────────────────────────────────────────────────────────────
SELECT\\n            rr.ITEM,\\n            rr.LOCATION,\\n            rr.LOC_TYPE,\\n            MAX(rr.REPL_DATE)                             AS last_roq_date,\\n            MAX(rr.ORDER_ROQ)\\n                KEEP (DENSE_RANK LAST ORDER BY rr.REPL_DATE)\\n                                                          AS last_roq_qty\\n        FROM  MFCS_RDS.RDS_WV_REPL_RESULTS         rr\\n        GROUP BY rr.ITEM, rr.LOCATION, rr.LOC_TYPE\\n    ) last_roq                                            ON  ril.ITEM     = last_roq.ITEM\\n                                                         AND  ril.LOCATION = last_roq.LOCATION\\n                                                         AND  ril.LOC_TYPE = last_roq.LOC_TYPE\\n\\n    LEFT JOIN (\\n

-- ── Query 8 ────────────────────────────────────────────────────────────
SELECT\\n            ol.ITEM,\\n            ol.LOCATION,\\n            COUNT(DISTINCT oh.ORDER_NO)                   AS open_po_count,\\n            SUM(ol.QTY_ORDERED - NVL(ol.QTY_RECEIVED, 0)) AS open_po_qty,\\n            MIN(oh.WRITTEN_DATE)                          AS oldest_po_date,\\n            MAX(oh.WRITTEN_DATE)                          AS newest_po_date\\n        FROM  MFCS_RDS.RDS_WV_ORDLOC               ol\\n        JOIN  MFCS_RDS.RDS_WV_ORDHEAD              oh  ON  ol.ORDER_NO = oh.ORDER_NO\\n        WHERE oh.STATUS IN ('W','S','A')\\n        GROUP BY ol.ITEM, ol.LOCATION\\n    ) open_po                                             ON  ril.ITEM     = open_po.ITEM\\n                                                         AND  ril.LOCATION = open_po.LOCATION\\n\\n    LEFT JOIN (\\n

-- ── Query 9 ────────────────────────────────────────────────────────────
SELECT\\n            td.ITEM,\\n            th.TO_LOC                                     AS loc,\\n            COUNT(DISTINCT th.TSF_NO)                     AS open_tsf_count,\\n            SUM(td.TSF_QTY - NVL(td.RECEIVED_QTY, 0))    AS open_tsf_qty,\\n            MIN(th.CREATE_DATE)                           AS oldest_tsf_date\\n        FROM  MFCS_RDS.RDS_WV_TSFDETAIL            td\\n        JOIN  MFCS_RDS.RDS_WV_TSFHEAD              th  ON  td.TSF_NO = th.TSF_NO\\n        WHERE th.STATUS IN ('A','S','IR')\\n        GROUP BY td.ITEM, th.TO_LOC\\n    ) open_tsf                                            ON  ril.ITEM     = open_tsf.ITEM\\n                                                         AND  ril.LOCATION = open_tsf.loc\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_SUPS_MIN_FAIL       smf  ON  ril.ITEM       = smf.ITEM\\n                                                        AND  ril.PRIMARY_REPL_SUPPLIER = smf.SUPPLIER\\n\\nWHERE\\n    ril.REPL_METHOD  IS NOT NULL\\n    AND il.STATUS    IN ('A','C')\\n    AND im.STATUS     = 'A'\\n    AND (\\n        last_rcpt.LAST_RECEIVE_DATE IS NULL\\n        OR (NVL(ils.STOCK_ON_HAND,0)=0\\n            AND NVL(open_po.OPEN_PO_QTY,0)=0\\n            AND NVL(open_tsf.OPEN_TSF_QTY,0)=0)\\n        OR smf.ITEM IS NOT NULL\\n        OR last_roq.LAST_ROQ_DATE IS NULL\\n        OR TRUNC(last_roq.LAST_ROQ_DATE) &lt; TRUNC(SYSDATE)-7\\n        OR (NVL(ils.STOCK_ON_HAND,0) &lt; NVL(ril.MIN_STOCK,0)\\n            AND NVL(open_po.OPEN_PO_QTY,0)=0\\n            AND NVL(open_tsf.OPEN_TSF_QTY,0)=0)\\n        OR NVL(sp.SUP_STATUS,'X') != 'A'\\n        OR (NVL(isc.PICKUP_LEAD_TIME,0)=0\\n            AND ril.STOCK_CAT IN ('C','D','L','W'))\\n        OR NVL(isc.UNIT_COST,0)=0\\n    )\\n\\nORDER BY\\n    (CASE WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL THEN 1 ELSE 0 END\\n     + CASE WHEN NVL(ils.STOCK_ON_HAND,0)=0\\n                 AND NVL(open_po.OPEN_PO_QTY,0)=0\\n                 AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 1 ELSE 0 END\\n     + CASE WHEN smf.ITEM IS NOT NULL THEN 1 ELSE 0 END\\n     + CASE WHEN last_roq.LAST_ROQ_DATE IS NULL\\n                 OR TRUNC(last_roq.LAST_ROQ_DATE) &lt; TRUNC(SYSDATE)-7 THEN 1 ELSE 0 END\\n     + CASE WHEN NVL(ils.STOCK_ON_HAND,0) &lt; NVL(ril.MIN_STOCK,0)\\n                 AND NVL(open_po.OPEN_PO_QTY,0)=0\\n                 AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 1 ELSE 0 END\\n     + CASE WHEN NVL(sp.SUP_STATUS,'X')!='A'\\n                 AND ril.STOCK_CAT IN ('C','D','L','W') THEN 1 ELSE 0 END\\n     + CASE WHEN NVL(isc.PICKUP_LEAD_TIME,0)=0\\n                 AND ril.STOCK_CAT IN ('C','D','L','W') THEN 1 ELSE 0 END\\n     + CASE WHEN NVL(isc.UNIT_COST,0)=0 THEN 1 ELSE 0 END\\n    ) DESC,\\n    CASE\\n        WHEN NVL(ils.STOCK_ON_HAND,0)=0\\n             AND NVL(open_po.OPEN_PO_QTY,0)=0\\n             AND NVL(open_tsf.OPEN_TSF_QTY,0)=0\\n        THEN 'CRITICAL - OOS with No Supply'\\n        WHEN smf.ITEM IS NOT NULL THEN 'HIGH - Supplier Minimum Failure'\\n        WHEN NVL(sp.SUP_STATUS,'X')!='A'\\n             AND ril.STOCK_CAT IN ('C','D','L','W') THEN 'HIGH - Inactive Supplier on Repl'\\n        WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL THEN 'HIGH - Never Received'\\n        WHEN NVL(ils.STOCK_ON_HAND,0) &lt; NVL(ril.MIN_STOCK,0)\\n             AND NVL(open_po.OPEN_PO_QTY,0)=0\\n             AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 'HIGH - Below Min, No Open Supply'\\n        ELSE 'MEDIUM'\\n    END,\\n    d.DEPT_NAME,\\n    im.ITEM_DESC,\\n    CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END;\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-07-14T15:50:03.918+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_527_Repl_Exception_Detail'","parent-namespace":"ReCommon","parent-name":"RPT_527_Repl_Exception_Detail","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_527_Repl_Exception_Detail'"}
